svg.script:
(function(){
 var ROOT=document.documentElement;
 var SVGNS='http://www.w3.org/2000/svg';
 var fig=document.getElementById('fig');
 var rain=document.getElementById('rain');
 var rg=document.getElementById('rg'),bg2=document.getElementById('bg2');
 var flash=document.getElementById('flash'),bars=document.getElementById('bars');
 var n=0,playing=false;
 function rnd(a,b){return a+Math.random()*(b-a);}
 function ease(p){return p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;}
 function easeOut(p){return 1-Math.pow(1-p,3);}
 function reset(){
   fig.removeAttribute('transform');fig.setAttribute('opacity',1);fig.style.filter='none';
   rain.innerHTML='';bars.innerHTML='';
   rg.setAttribute('opacity',0);bg2.setAttribute('opacity',0);
   rg.removeAttribute('transform');bg2.removeAttribute('transform');
   flash.setAttribute('opacity',0);
 }
 function run(dur,step,done){
   var t0=null;
   function fr(t){
     if(t0===null)t0=t;var p=(t-t0)/dur;if(p>1)p=1;
     step(p);
     if(p<1)requestAnimationFrame(fr);else{if(done)done();reset();playing=false;}
   }
   requestAnimationFrame(fr);
 }

 // ===== EFFECT 1: BLOCKCHAIN MATERIALIZE (PEPE rain) =====
 function materialize(){
   var word='PEPE',cols=[];
   rain.innerHTML='';
   for(var x=12;x<388;x+=12){
     var len=4+((Math.random()*8)|0),trail=[],wi=(Math.random()*4)|0;
     for(var i=0;i<len;i++){
       var t=document.createElementNS(SVGNS,'text');
       t.setAttribute('class','glyph');t.setAttribute('x',x);t.setAttribute('y',-i*10);
       t.textContent=word[(wi+i)%4];
       t.setAttribute('opacity',(1-i/len).toFixed(2));
       rain.appendChild(t);trail.push(t);
     }
     cols.push({trail:trail,sp:1.6+Math.random()*2.4,wi:wi});
   }
   run(2200,function(p){
     fig.setAttribute('opacity',(p<.45?(1-p/.45):((p-.45)/.55)).toFixed(2));
     var fade=p<.45?1:(1-(p-.45)/.55);
     cols.forEach(function(c){
       c.trail.forEach(function(g,i){
         var y=parseFloat(g.getAttribute('y'))+c.sp*4;
         if(y>580){y=-i*10-(Math.random()*40);}
         g.setAttribute('y',y);
         if(Math.random()<.05){g.textContent=word[(Math.random()*4)|0];}
         g.setAttribute('opacity',((1-i/c.trail.length)*fade).toFixed(2));
       });
     });
   });
 }

 // ===== EFFECT 2: SHATTER & REFORM =====
 function shatter(){
   var shapes=[].slice.call(fig.querySelectorAll('polygon,rect,path,ellipse'));
   var data=shapes.map(function(s){
     var b=s.getBBox(),cx=b.x+b.width/2,cy=b.y+b.height/2;
     var ang=Math.atan2(cy-300,cx-200)+(Math.random()-.5);
     var dist=120+Math.random()*180;
     return {s:s,dx:Math.cos(ang)*dist,dy:Math.sin(ang)*dist,r:(Math.random()-.5)*720,ox:cx,oy:cy};
   });
   run(1500,function(p){
     var out=p<.45?ease(p/.45):1-ease((p-.45)/.55);
     data.forEach(function(d){
       var sc=1-.15*out;
       d.s.setAttribute('transform',
         'translate('+(d.ox+d.dx*out)+' '+(d.oy+d.dy*out)+') rotate('+(d.r*out)+') scale('+sc+') translate('+(-d.ox)+' '+(-d.oy)+')');
     });
   },function(){data.forEach(function(d){d.s.removeAttribute('transform');});});
 }

 // ===== EFFECT 3: GLITCH ASCENSION (+2s, DUR 3600) =====
 function glitch(){
   run(3600,function(p){
     if(p<.78){ // glitch phase stretched proportionally (was .7 of 1600; snap window kept ~0.8s)
       var amp=(1-p/.78);
       var sx=rnd(-1,1)*8*amp;
       rg.setAttribute('opacity',(.7*amp+.3).toFixed(2));
       bg2.setAttribute('opacity',(.7*amp+.3).toFixed(2));
       rg.setAttribute('transform','translate('+sx+' '+(rnd(-2,2)*amp)+')');
       bg2.setAttribute('transform','translate('+(-sx)+' '+(rnd(-2,2)*amp)+')');
       fig.setAttribute('transform','translate('+(rnd(-1,1)*6*amp)+' '+(rnd(-1,1)*14*amp)+')');
       if(Math.random()<.5){
         bars.innerHTML='';
         var cnt=2+((Math.random()*4)|0);
         for(var i=0;i<cnt;i++){
           var y=rnd(120,470),h=rnd(3,18);
           var r=document.createElementNS(SVGNS,'rect');
           r.setAttribute('x',0);r.setAttribute('y',y);r.setAttribute('width',400);r.setAttribute('height',h);
           r.setAttribute('fill',Math.random()<.5?'#0CA30A':'#003000');
           r.setAttribute('opacity',(rnd(.2,.6)*amp).toFixed(2));
           bars.appendChild(r);
         }
       }
     } else {
       var q=(p-.78)/.22;
       rg.setAttribute('opacity',0);bg2.setAttribute('opacity',0);
       rg.removeAttribute('transform');bg2.removeAttribute('transform');
       bars.innerHTML='';fig.removeAttribute('transform');
       flash.setAttribute('opacity',(q<.2?q*4:Math.max(0,.8-(q-.2))).toFixed(2));
     }
   });
 }

 var effects=[materialize,shatter,glitch];
 ROOT.addEventListener('click',function(){
   if(playing)return;
   playing=true;reset();
   effects[n%3]();n++;
 });
})();
